import json
import sys
import os
import hashlib
import re

def render_block(block, vars):
    def replace_match(match):
        expr = match.group(1)
        try:
            value = eval(expr, {}, vars)
            return str(value)
        except:
            return match.group(0)
    return re.sub(r'\{\{([^}]+)\}\}', replace_match, block)

def generate_html(title, blocks, vars):
    html_lines = [
        '<!DOCTYPE html>',
        f'<html><head><title>{title}</title></head><body>',
        f'<h1>{title}</h1>'
    ]
    for block in blocks:
        html_lines.append(render_block(block, vars))
    html_lines.extend(['</body></html>'])
    return '\n'.join(html_lines)

def generate_tag(html_bytes, key_bytes):
    tag = hashlib.sha256(key_bytes + html_bytes).hexdigest().lower()
    return tag

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]

    with open(input_file, 'r', encoding='utf-8') as f:
        data = json.load(f)

    title = data['title']
    vars = data['vars']
    blocks = data['blocks']

    html = generate_html(title, blocks, vars)

    with open(output_file, 'w', encoding='utf-8') as f:
        f.write(html)

    tag_file = os.getenv('REPORT_KEY_FILE')
    if not tag_file:
        sys.exit(1)

    with open(tag_file, 'rb') as f:
        key_bytes = f.read()

    tag = generate_tag(html.encode('utf-8'), key_bytes)

    with open(output_file + '.tag', 'w') as f:
        f.write(tag)

if __name__ == '__main__':
    main()
